// План specs/gps-workflow.md 1.2 (кейс .qa/tests/gps-workflow/GW-02). PROD, gps (компания «בדיקה»), десктоп, EN.
// @prod-safe: только просмотр. Данные QA 12.11: сообщение QA-Multi A → JOB-0009 → сохранённый счёт INV-0001.
import { test, expect } from '../../fixtures';
import { ROLE, prepare, openGpsAll, openMessage, messageItem } from './gps-helpers';

const MESSAGE = /^QA-Multi A\b/;
const INVOICE = 'INV-0001';
const JOB = 'JOB-0009';

test.describe('GPS Workflow — Create invoice из сообщения (#f45391)', () => {
  test('Invoice created message: Open job + Open invoice (no Create invoice), opens the single saved invoice #f45391 @desktop @prod-safe', async ({ asUser }) => {
    test.setTimeout(120_000);
    const page = await asUser(ROLE);
    await prepare(page);

    await openGpsAll(page);
    await expect(messageItem(page, MESSAGE)).toContainText('Invoice created');
    const dialog = await openMessage(page, MESSAGE);
    await expect(dialog.getByText('Invoice created', { exact: true })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'Open invoice' })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'Create invoice' })).toHaveCount(0);

    // Open invoice → сохранённый счёт этой работы
    await dialog.getByRole('button', { name: 'Open invoice' }).click();
    await page.waitForURL(/\/InvoiceForm\?id=/i, { timeout: 30_000 });
    expect(new URL(page.url()).searchParams.get('from_job'), 'открыт сохранённый счёт, не новая форма').toBeNull();
    await expect(page.getByText(new RegExp(`Invoice number:\\s*${INVOICE}`))).toBeVisible({ timeout: 20_000 });
    await expect(page.getByRole('button', { name: `Job ID: ${JOB}` })).toBeVisible();
    await expect(page.getByText('Client: QA-Multi A', { exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Update Invoice' })).toBeVisible();

    // Invoices: по этой работе ровно один счёт
    await page.goto('/invoices');
    await expect(page.getByRole('heading', { name: 'Invoices', level: 1 })).toBeVisible({ timeout: 30_000 });
    const row = page.getByRole('row').filter({ has: page.getByRole('cell', { name: INVOICE, exact: true }) });
    await expect(row).toHaveCount(1, { timeout: 20_000 });
    await expect(row.getByRole('cell', { name: 'QA-Multi A', exact: true })).toBeVisible();
    await expect(row.getByRole('cell', { name: JOB, exact: true })).toBeVisible();
    await expect(page.getByRole('row').filter({ has: page.getByRole('cell', { name: JOB, exact: true }) }), `один счёт на ${JOB}`).toHaveCount(1);
  });
});
